// Tenta localizar a resposta produzida pelo LLM
let raw =
  $json.text ??
  $json.output ??
  $json.response ??
  $json;

// Se vier como texto, limpa markdown e transforma em objeto
if (typeof raw === 'string') {

  raw = raw
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    raw = JSON.parse(raw);
  } catch (error) {
    throw new Error(
      'A resposta da IA não é um JSON válido. Resposta recebida: ' + raw
    );
  }
}

// Alguns modelos podem devolver:
// { "output": { ... } }
if (raw.output && typeof raw.output === 'object') {
  raw = raw.output;
}

const requisitos = Array.isArray(raw.requisitos)
  ? raw.requisitos
  : [];

let pontos = 0;

for (const requisito of requisitos) {

  const status = String(requisito.status || '')
    .trim()
    .toUpperCase();

  if (status === 'ATENDIDO') {
    pontos += 1;
  } else if (status === 'PARCIALMENTE_ATENDIDO') {
    pontos += 0.5;
  }
}

const totalRequisitos = requisitos.length;

const match = totalRequisitos > 0
  ? Math.round((pontos / totalRequisitos) * 100)
  : 0;

return {
  json: {
    requisitos,

    pontos_fortes:
      Array.isArray(raw.pontos_fortes)
        ? raw.pontos_fortes
        : [],

    lacunas:
      Array.isArray(raw.lacunas)
        ? raw.lacunas
        : [],

    justificativa_resumida:
      raw.justificativa_resumida || '',

    total_requisitos: totalRequisitos,
    pontos_obtidos: pontos,
    match
  }
};
